function parseFlags(argv) {
  const flags = { _: [] };

  for (const arg of argv) {
    if (!arg.startsWith('--')) {
      flags._.push(arg);
      continue;
    }

    const name = arg.slice(2);
    const eq = name.indexOf('=');

    if (eq === -1) {
      flags[name] = true;
    } else {
      flags[name.slice(0, eq)] = name.slice(eq + 1);
    }
  }

  return flags;
}

module.exports = { parseFlags };

const test = require('node:test');
const assert = require('node:assert/strict');

const { parseFlags } = require('../src/flags');

test('returns only an empty positional list for empty argv', () => {
  assert.deepEqual(parseFlags([]), { _: [] });
});

test('sets a string value for --name=value', () => {
  assert.deepEqual(parseFlags(['--out=x']), { _: [], out: 'x' });
});

test('sets true for --name without a value', () => {
  assert.deepEqual(parseFlags(['--verbose']), { _: [], verbose: true });
});

test('collects non-flag arguments under _ in order', () => {
  assert.deepEqual(parseFlags(['a', 'b']), { _: ['a', 'b'] });
});

test('handles flags and positionals together', () => {
  assert.deepEqual(parseFlags(['--verbose', '--out=x', 'a']), {
    _: ['a'],
    verbose: true,
    out: 'x',
  });
});
